const data = $input.first().json;
const body = data.body || data;

const stats = body.stats || {};
const suite = body.suite || 'Cypress Regression - BUPA';
const fecha = body.fecha || new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const results = body.results || [];

const totalTests = stats.tests || 0;
const passes = stats.passes || 0;
const failures = stats.failures || 0;
const pending = totalTests - passes - failures;
const durationMs = stats.duration || 0;
const durationSec = Math.round(durationMs / 1000);
const durationStr = durationSec >= 60
  ? Math.floor(durationSec / 60) + 'm ' + (durationSec % 60) + 's'
  : durationSec + 's';

const allPassed = failures === 0;
const statusText = allPassed ? 'PASS' : 'FAIL';

// Obtener nombre del spec y carpeta desde los runs
const specNames = (results || []).map(r => {
  const f = r.file || '';
  return f.split('/').pop().replace('.cy.js', '').replace('.cy.ts', '');
}).filter(Boolean);
const folders = [...new Set((results || []).map(r => {
  const parts = (r.file || '').split('/');
  return parts.length >= 2 ? parts[parts.length - 2] : '';
}).filter(Boolean))];
let specLabel;
if (specNames.length === 1) {
  specLabel = specNames[0];
} else if (specNames.length > 1) {
  specLabel = folders.join(', ') + ' (' + specNames.length + ' specs)';
} else {
  specLabel = suite;
}

// Parse todos los tests
const allTests = [];
for (const run of results) {
  const specFile = (run.file || '').split('/').pop().replace('.cy.js', '').replace('.cy.ts', '');
  for (const test of (run.tests || [])) {
    const titleStr = test.title || '';
    const parts = titleStr.split(' > ');
    const itPart = parts.length > 1 ? parts.slice(1).join(' > ') : titleStr;

    allTests.push({
      spec: specFile || 'N/A',
      testCase: itPart.trim(),
      state: test.state || 'unknown',
      duration: test.duration || 0,
      error: test.err ? (test.err.length > 200 ? test.err.substring(0, 200) + '...' : test.err) : '\u2014'
    });
  }
}

// Subject
const subject = 'Portal Pacientes \uD83E\uDDEA Cypress# ' + specLabel + ' ' + statusText + ' \u2014 ' + passes + '\u2705 ' + failures + '\u274C | ' + fecha;

// Badge
const badgeHtml = allPassed
  ? '<span style="background:#F0FDF4; color:#16A34A; padding:6px 16px; border-radius:16px; font-weight:700; font-size:13px; white-space:nowrap;">\u2705 TODO PASSED</span>'
  : '<span style="background:#FEF2F2; color:#DC2626; padding:6px 16px; border-radius:16px; font-weight:700; font-size:13px; white-space:nowrap;">\u274C HAY FALLOS</span>';

// Cards
const cardHtml = (value, label, color, bg) => {
  return '<td width="25%" style="padding:4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + bg + '; border-left:4px solid ' + color + '; border-radius:6px;"><tr><td style="padding:14px 16px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:28px; font-weight:700; color:' + color + '; line-height:1;">' + value + '</div><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; font-weight:700; letter-spacing:1px; color:#64748B; text-transform:uppercase; margin-top:4px;">' + label + '</div></td></tr></table></td>';
};

const cards = cardHtml(passes, '\u2705 PASADOS', '#16A34A', '#F0FDF4')
  + cardHtml(failures, '\u274C FALLIDOS', '#DC2626', '#FEF2F2')
  + cardHtml(pending, '\u26A0\uFE0F PENDIENTES', '#F59E0B', '#FFFBEB')
  + cardHtml(durationStr, '\u23F1 DURACION', '#2563EB', '#EFF6FF');

// Table rows
const tableRows = allTests.map((t) => {
  let sColor, sBg, sLabel;
  if (t.state === 'passed') { sColor = '#16A34A'; sBg = '#F0FDF4'; sLabel = 'PASSED'; }
  else if (t.state === 'failed') { sColor = '#DC2626'; sBg = '#FEF2F2'; sLabel = 'FAILED'; }
  else { sColor = '#F59E0B'; sBg = '#FFFBEB'; sLabel = 'PENDING'; }
  const dot = t.state === 'passed' ? '\uD83D\uDFE2' : t.state === 'failed' ? '\uD83D\uDD34' : '\uD83D\uDFE1';

  return '<tr>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:16px; text-align:center;">' + dot + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;">' + t.spec + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;">' + t.testCase + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + sBg + '; color:' + sColor + '; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px; letter-spacing:0.5px; font-family:Segoe UI,Helvetica,Arial,sans-serif;">' + sLabel + '</span></td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#2563EB; font-weight:600; text-align:center;">' + t.duration + 'ms</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#94A3B8; max-width:220px; word-break:break-word;">' + t.error + '</td>'
    + '</tr>';
}).join('');

// Full HTML - mismo diseño que WF-1
const htmlBody = '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; max-width:760px; margin:0 auto; background:#F4F6FB;">'

  // Header azul
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#0747A6;">'
  + '<tr><td style="padding:28px 28px;" valign="top">'
  + '<div style="color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;">BUPA CHILE \u00B7 PORTAL PACIENTES</div>'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:10px;"><tr>'
  + '<td style="vertical-align:middle;">'
  + '<div style="color:#FFFFFF; font-size:18px; font-weight:700;">'
  + '<span style="background:rgba(255,255,255,0.15); padding:3px 10px; border-radius:5px; margin-right:6px; font-size:13px; font-weight:800;">Cypress</span>'
  + '#Test Regresion# ' + specLabel + '</div>'
  + '<div style="color:#CFE2FF; font-size:13px; margin-top:6px;">' + totalTests + ' test(s) ejecutados \u00B7 ' + fecha + '</div>'
  + '</td>'
  + '<td style="text-align:right; vertical-align:middle;">' + badgeHtml + '</td>'
  + '</tr></table>'
  + '</td></tr></table>'

  // Cards
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:16px 20px;">'
  + '<tr>' + cards + '</tr></table>'

  // Detalle header
  + '<div style="padding:4px 20px 8px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:8px;">DETALLE DE TESTS</div></div>'

  // Table
  + '<div style="padding:0 20px 24px; overflow-x:auto;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);">'
  + '<thead><tr style="background:#F4F6F8;">'
  + '<th style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B; width:30px;"></th>'
  + '<th align="left" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Spec</th>'
  + '<th align="left" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Test Case</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Estado</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Duracion</th>'
  + '<th align="left" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Error</th>'
  + '</tr></thead>'
  + '<tbody>' + tableRows + '</tbody></table></div>'

  // Footer
  + '<div style="padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;">'
  + 'Generado autom\u00E1ticamente \u2014 WF-2 Cypress Test Execution \u00B7 Portal Pacientes'
  + '</div></div>';

return [{ json: { subject, body: htmlBody } }];

